edit(43189,[('Private saving','At every given real interest rate, planned private saving')], 'Make the private/public changes schedule shifts rather than an unstated final equilibrium constraint.',True)
edit(43227,[('private saving','private-saving behavior')], 'Hold private-saving behavior fixed rather than its final quantity in the deficit mechanism.')
edit(43252,[('output and consumption remain fixed','output remains fixed and the consumption schedule is unchanged at each given real rate')], 'Make the fiscal graph shift consistent with a rate-responsive private-saving schedule.')
edit(43264,[('Public saving falls','At every given real interest rate, public saving falls'),('private saving rises','planned private saving rises')], 'Specify the fixed-rate fiscal and private-saving changes underlying the supply shift.',True)
edit(43154,[('Which sequence stays within the intended Principles-level boundary?','A government raises purchases with net taxes unchanged. Private-saving behavior is unchanged. Which sequence describes the fiscal consequence?')], 'Replace a curriculum-boundary prompt with a student-facing fiscal application.')
edit(43162,[(', last updated August 26, 2026','')], 'Remove a moving dataset-update claim while preserving the dated-observation skill.')
s['43162']['q']=s['43162']['q'].replace('dataset, reports','dataset reports')
s['43203']['q']=s['43203']['q'].replace('without shift magnitudes','without knowing the investment-demand shift magnitude')
s['43203']['feedback']='At each given real rate, planned national saving falls by $15 billion, shifting supply left. Technology shifts investment demand right. Both shifts raise the real rate, but their quantity effects oppose one another; the final change in realized saving and investment is therefore not fixed at −$15 billion.'
s['43210']['feedback']='At each given real rate, lower purchases raise planned national saving by $25 billion and shift supply right. Stronger sales expectations shift investment demand right. Both raise equilibrium quantity, but their opposing rate pressures make the rate depend on relative shift magnitudes.'
s['43154']['options']=['Public saving falls and the budget moves toward deficit, increasing borrowing needs if the shortfall is debt-financed','Private saving falls but public saving is unchanged, because government purchases are household consumption','Public saving rises and the budget moves toward surplus, reducing the need to issue government debt','Public saving falls but issuing debt counts as revenue, so borrowing restores the budget balance']
s['43154']['feedback']='With net taxes unchanged, higher government purchases reduce public saving T − G and move the budget toward deficit. Borrowing can finance the shortfall, but debt issuance does not count as revenue or reverse the decline in public saving.'
(W/'revisions.json').write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n','utf8')
print(f'{len(s)} targeted content revisions, {sum(x["numeric"] for x in s.values())} numeric.')
